8: (function (global) {
9:   'use strict';
10: 
11:   var CinejoyApp = {
12:     // Current Application State
13:     state: {
14:       initialized: false,
15:       currentView: 'home',
16:       previousView: null,
17:       detailsOriginView: null,
18:       searchQuery: '',
19:       activeDetailItem: null,
20:       focusedElement: null
