26:     /**
27:      * Initialize application on DOM ready
28:      */
29:     init: function () {
30:       if (this.state.initialized) {
31:         return;
32:       }
33:       this.state.initialized = true;
34:       console.log('[CinejoyApp] Initializing 10-foot TV application shell...');
35: 
36:       var self = this;
37:       if (typeof window !== 'undefined' && window.SpatialNav) {
38:         window.SpatialNav.init({
39:           onBack: function () {
40:             return self.handleBackNavigation();
41:           },
42:           onSelect: function (element) {
43:             if (element && typeof element.click === 'function') {
44:               element.click();
45:             }
46:           },
47:           onMediaKey: function (data) {
48:             self.handleMediaKey(data.action);
49:           },
50:           onColorKey: function (data) {
51:             self.handleColorKey(data.color);
52:           }
53:         });
54: 
55:         window.SpatialNav.on('focus', function (data) {
56:           if (data && data.element) {
57:             self.state.focusedElement = data.element;
58:           }
59:         });
60:       }
