173:     /**
174:      * Switch view between home, movies, series, search, details, player
175:      * @param {string} viewName - Target view name
176:      * @param {Object} [data] - Optional payload for view
177:      */
178:     switchView: function (viewName, data) {
179:       if (this.views.indexOf(viewName) === -1) {
180:         console.warn('[CinejoyApp] Unknown view: ' + viewName);
181:         return;
182:       }
183: 
184:       console.log('[CinejoyApp] Switching view: ' + this.state.currentView + ' -> ' + viewName);
185:       if (this.state.currentView && typeof window !== 'undefined' && window.SpatialNav) {
186:         window.SpatialNav.saveFocus(this.state.currentView);
187:       }
188: 
189:       if (this.state.currentView === 'search' && viewName !== 'search' && global.SearchViewController) {
190:         global.SearchViewController.deactivate();
191:       }
192: 
193:       if (this.state.currentView === 'player' && viewName !== 'player' && global.PlayerController) {
194:         global.PlayerController.deactivate();
195:       }
196: 
197:       if (viewName === 'details') {
198:         if (this.state.currentView !== 'details' && this.state.currentView !== 'player') {
199:           this.state.detailsOriginView = this.state.currentView;
200:         }
201:       } else if (viewName !== 'player') {
202:         this.state.detailsOriginView = null;
203:       }
204: 
205:       this.state.previousView = this.state.currentView;
206:       this.state.currentView = viewName;
207: 
208:       // Update URL hash
209:       if (window.location.hash !== '#' + viewName) {
210:         window.location.hash = '#' + viewName;
211:       }
212: 
213:       // Hide all views
214:       var allViews = document.querySelectorAll('.view');
215:       allViews.forEach(function (v) {
216:         v.classList.remove('active');
217:       });
218: 
219:       // Show target view
220:       var targetViewEl = document.getElementById('view-' + viewName);
221:       if (targetViewEl) {
222:         targetViewEl.classList.add('active');
223:         // Reset scroll position to top
224:         var scrollPane = targetViewEl.querySelector('.view-scroll-pane');
225:         if (scrollPane) {
226:           scrollPane.scrollTop = 0;
227:         }
228:       }
229: 
230:       // Invoke view controller activate hooks if present
231:       if (viewName === 'home' && global.HomeViewController) {
232:         global.HomeViewController.activate();
233:       } else if (viewName === 'movies' && global.MoviesViewController) {
234:         global.MoviesViewController.activate();
235:       } else if (viewName === 'series' && global.SeriesViewController) {
236:         global.SeriesViewController.activate();
237:       } else if (viewName === 'search' && global.SearchViewController) {
238:         global.SearchViewController.activate();
239:       } else if (viewName === 'details' && global.DetailsViewController) {
240:         global.DetailsViewController.activate(data);
241:       } else if (viewName === 'player' && global.PlayerController) {
242:         global.PlayerController.activate(data);
243:       }
244: 
245:       // Header Visibility & Active Nav Item
246:       var header = document.querySelector('.app-header');
247:       if (header) {
248:         if (viewName === 'player') {
249:           header.classList.add('header-hidden');
250:         } else {
251:           header.classList.remove('header-hidden');
252:         }
253:       }
254: 
255:       // Update Header active indicator
256:       var navItems = document.querySelectorAll('.nav-pill-item');
257:       navItems.forEach(function (item) {
258:         if (item.getAttribute('data-route') === viewName) {
259:           item.classList.add('active');
260:         } else {
261:           item.classList.remove('active');
262:         }
263:       });
264: 
265:       // If opening player view, handle video playback element
266:       var videoEl = document.getElementById('main-video-player');
267:       if (viewName === 'player') {
268:         if (videoEl && videoEl.paused) {
269:           // Video element ready for playback
270:         }
271:       } else if (videoEl && !videoEl.paused) {
272:         videoEl.pause();
273:       }
274: 
275:       // Set focus to the first navigable element in the new view
276:       this.focusFirstElementInView(viewName);
