307:     /**
308:      * Set focus on target element and apply high-contrast focus ring
309:      * @param {HTMLElement} element
310:      */
311:     setFocus: function (element) {
312:       if (!element) return;
313: 
314:       if (typeof window !== 'undefined' && window.SpatialNav) {
315:         window.SpatialNav.setFocus(element);
316:         this.state.focusedElement = element;
317:         return;
318:       }
319: 
320:       // Fallback if SpatialNav is not present
321:       if (this.state.focusedElement && this.state.focusedElement !== element) {
322:         this.state.focusedElement.classList.remove('focused', 'tv-focused');
323:       }
324: 
325:       this.state.focusedElement = element;
326:       element.classList.add('focused', 'tv-focused');
327: 
328:       // Native focus if applicable
329:       if (typeof element.focus === 'function') {
330:         try {
331:           element.focus({ preventScroll: true });
332:         } catch (_) {}
333:       }
334: 
335:       // Ensure element is visible inside its scrollable parent
336:       if (typeof element.scrollIntoView === 'function') {
337:         try {
338:           element.scrollIntoView({
339:             behavior: 'smooth',
340:             block: 'nearest',
341:             inline: 'nearest'
342:           });
343:         } catch (_) {}
344:       }
345:     },
