347:     /**
348:      * Focus first navigable element in given view
349:      */
350:     focusFirstElementInView: function (viewName) {
351:       if (this.state.currentView !== viewName) return;
352: 
353:       var viewEl = document.getElementById('view-' + viewName);
354:       if (!viewEl) return;
355: 
356:       if (viewName === 'player') {
357:         var playBtn = document.getElementById('osd-play-btn');
358:         if (playBtn) {
359:           this.setFocus(playBtn);
360:           return;
361:         }
362:       }
363: 
364:       // Do not hijack focus if user already navigated to an element inside this view
365:       if (this.state.focusedElement && viewEl.contains(this.state.focusedElement)) {
366:         return;
367:       }
368: 
369:       if (typeof window !== 'undefined' && window.SpatialNav) {
370:         var restored = window.SpatialNav.restoreFocus(viewName);
371:         if (restored) {
372:           this.state.focusedElement = restored;
373:           return;
374:         }
375:       }
376: 
377:       // Prefer #osd-play-btn or default nav in view, or first element marked data-nav="true"
378:       var firstNav = viewEl.querySelector('#osd-play-btn') ||
379:                      viewEl.querySelector('[data-nav-default="true"]') ||
380:                      viewEl.querySelector('[data-nav="true"]');
381:       if (firstNav) {
382:         this.setFocus(firstNav);
383:       } else {
384:         // Fallback to active header pill
385:         var activeNavPill = document.querySelector('.nav-pill-item.active');
386:         if (activeNavPill) {
387:           this.setFocus(activeNavPill);
388:         }
389:       }
390:     },
