392:     /**
393:      * Set initial focus on app launch
394:      */
395:     setInitialFocus: function () {
396:       var initialFocus = document.querySelector('.nav-pill-item.active') ||
397:                          document.querySelector('[data-nav="true"]');
398:       if (initialFocus) {
399:         this.setFocus(initialFocus);
400:       }
