403:     /**
404:      * Handle remote control and keyboard navigation
405:      */
406:     handleKeyDown: function (e) {
407:       // If SpatialNav is enabled on the window, it manages all remote key events
408:       if (typeof window !== 'undefined' && window.SpatialNav && window.SpatialNav.isEnabled && window.SpatialNav.isEnabled()) {
409:         return;
410:       }
411: 
412:       var key = e.key;
413:       var keyCode = e.keyCode;
414: 
415:       // webOS Back Key (keycode 461), Escape (27), Backspace
416:       if (keyCode === 461 || key === 'Escape') {
417:         e.preventDefault();
418:         this.handleBackNavigation();
419:         return;
420:       }
421: 
422:       // Enter / OK key (keycode 13)
423:       if (key === 'Enter' || keyCode === 13) {
424:         if (this.state.focusedElement) {
425:           this.state.focusedElement.click();
426:         }
427:         return;
428:       }
429: 
430:       // Spatial Arrow keys
431:       if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].indexOf(key) !== -1) {
432:         this.navigateSpatial(key, e);
433:       }
434:     },
