436:     /**
437:      * Back button hierarchical handler
438:      */
439:     handleBackNavigation: function () {
440:       if (this.state.currentView === 'player') {
441:         if (global.PlayerOSDController && global.PlayerOSDController._activeModal) {
442:           global.PlayerOSDController.closeActiveModal();
443:           return true;
444:         }
445:         this.exitPlayer();
446:         return true;
447:       } else if (this.state.currentView === 'details') {
448:         var returnView = this.state.detailsOriginView || this.state.previousView || 'home';
449:         if (returnView === 'details' || returnView === 'player') returnView = 'home';
450:         this.state.detailsOriginView = null;
451:         this.switchView(returnView);
452:         return true;
453:       } else if (this.state.currentView !== 'home') {
454:         this.switchView('home');
455:         return true;
456:       } else {
457:         console.log('[CinejoyApp] Back pressed on home view. (webOS app exit threshold)');
458:         return true;
459:       }
460:     },
