462:     /**
463:      * Handle remote control media keys
464:      */
465:     handleMediaKey: function (action) {
466:       if (this.state.currentView === 'player' && global.PlayerController) {
467:         switch (action) {
468:           case 'MEDIA_PLAY':
469:             global.PlayerController.play();
470:             if (global.PlayerOSDController) global.PlayerOSDController.resetIdleTimer();
471:             return;
472:           case 'MEDIA_PAUSE':
473:             global.PlayerController.pause();
474:             if (global.PlayerOSDController) global.PlayerOSDController.showHUD();
475:             return;
476:           case 'MEDIA_PLAY_PAUSE':
477:             global.PlayerController.togglePlayPause();
478:             return;
479:           case 'MEDIA_STOP':
480:             this.exitPlayer();
481:             return;
482:           case 'MEDIA_FAST_FORWARD':
483:             global.PlayerController.seek(10);
484:             if (global.PlayerOSDController) global.PlayerOSDController.showSeekFeedback(true, 10);
485:             return;
486:           case 'MEDIA_REWIND':
487:             global.PlayerController.seek(-10);
488:             if (global.PlayerOSDController) global.PlayerOSDController.showSeekFeedback(false, 10);
489:             return;
490:         }
491:       }
492: 
493:       var video = document.getElementById('main-video-player');
494:       if (!video) return;
495: 
496:       switch (action) {
497:         case 'MEDIA_PLAY':
498:           try { video.play(); } catch (_) {}
499:           break;
500:         case 'MEDIA_PAUSE':
501:           try { video.pause(); } catch (_) {}
502:           break;
503:         case 'MEDIA_PLAY_PAUSE':
504:           try {
505:             if (video.paused) video.play();
506:             else video.pause();
507:           } catch (_) {}
508:           break;
509:         case 'MEDIA_STOP':
510:           try { video.pause(); } catch (_) {}
511:           this.exitPlayer();
512:           break;
513:         case 'MEDIA_FAST_FORWARD':
514:           try { video.currentTime = Math.min(video.duration || Infinity, video.currentTime + 10); } catch (_) {}
515:           break;
516:         case 'MEDIA_REWIND':
517:           try { video.currentTime = Math.max(0, video.currentTime - 10); } catch (_) {}
518:           break;
519:       }
520:     },
