536:           var inputDisplay2 = document.getElementById('search-query-text');
537:           var placeholder2 = document.getElementById('search-query-placeholder');
538:           if (inputDisplay2) inputDisplay2.textContent = this.state.searchQuery;
539:           if (placeholder2) placeholder2.style.display = 'none';
540:           this.updateSearchResults(this.state.searchQuery);
541:         } else if (color === 'yellow' || color === 'blue') {
542:           var firstResult = document.querySelector('#search-results-grid [data-nav="true"]');
543:           if (firstResult) {
544:             this.setFocus(firstResult);
545:           } else if (color === 'blue') {
546:             this.switchView('home');
547:           }
548:         }
549:       } else if (this.state.currentView === 'player') {
550:         if (color === 'red') {
551:           var subBtn = document.getElementById('osd-subtitles-btn');
552:           if (subBtn) subBtn.click();
553:         } else if (color === 'green') {
554:           var srvBtn = document.getElementById('osd-server-btn');
555:           if (srvBtn) srvBtn.click();
556:         } else if (color === 'blue') {
557:           this.exitPlayer();
558:         }
559:       } else {
560:         if (color === 'red') this.switchView('search');
561:         else if (color === 'green') this.switchView('movies');
562:         else if (color === 'yellow') this.switchView('series');
563:         else if (color === 'blue') this.switchView('home');
564:       }
