567:     /**
568:      * Spatial 2D navigation algorithm between navigable items
569:      */
570:     navigateSpatial: function (direction, event) {
571:       if (typeof window !== 'undefined' && window.SpatialNav) {
572:         var moved = window.SpatialNav.move(direction, event);
573:         if (moved) {
574:           this.state.focusedElement = moved;
575:         }
576:         return;
577:       }
578: 
579:       var current = this.state.focusedElement;
580:       if (!current || !document.body.contains(current)) {
581:         this.setInitialFocus();
582:         return;
583:       }
584: 
585:       var currentRect = current.getBoundingClientRect();
586:       var activeView = document.getElementById('view-' + this.state.currentView);
587:       var navCandidates = [];
588: 
589:       // Include header nav items if header is visible
590:       var header = document.querySelector('.app-header');
591:       if (header && !header.classList.contains('header-hidden')) {
592:         var headerNavs = header.querySelectorAll('[data-nav="true"]');
593:         for (var h = 0; h < headerNavs.length; h++) {
594:           navCandidates.push(headerNavs[h]);
595:         }
596:       }
597: 
598:       // Include view nav items
599:       if (activeView) {
600:         var viewNavs = activeView.querySelectorAll('[data-nav="true"]');
601:         for (var v = 0; v < viewNavs.length; v++) {
602:           navCandidates.push(viewNavs[v]);
603:         }
604:       }
605: 
606:       var bestCandidate = null;
607:       var minDistance = Infinity;
608: 
609:       for (var i = 0; i < navCandidates.length; i++) {
610:         var cand = navCandidates[i];
611:         if (cand === current) continue;
612: 
613:         var candRect = cand.getBoundingClientRect();
614:         if (candRect.width === 0 || candRect.height === 0) continue;
615: 
616:         var isDirectional = false;
617:         var primaryDiff = 0;
618:         var secondaryDiff = 0;
619: 
620:         var currentCenterX = currentRect.left + currentRect.width / 2;
621:         var currentCenterY = currentRect.top + currentRect.height / 2;
622:         var candCenterX = candRect.left + candRect.width / 2;
623:         var candCenterY = candRect.top + candRect.height / 2;
624: 
625:         if (direction === 'ArrowRight' && candRect.left >= currentRect.right - 10) {
626:           isDirectional = true;
627:           primaryDiff = candRect.left - currentRect.right;
628:           secondaryDiff = Math.abs(candCenterY - currentCenterY);
629:         } else if (direction === 'ArrowLeft' && candRect.right <= currentRect.left + 10) {
630:           isDirectional = true;
631:           primaryDiff = currentRect.left - candRect.right;
632:           secondaryDiff = Math.abs(candCenterY - currentCenterY);
633:         } else if (direction === 'ArrowDown' && candRect.top >= currentRect.bottom - 10) {
634:           isDirectional = true;
635:           primaryDiff = candRect.top - currentRect.bottom;
636:           secondaryDiff = Math.abs(candCenterX - currentCenterX);
637:         } else if (direction === 'ArrowUp' && candRect.bottom <= currentRect.top + 10) {
638:           isDirectional = true;
639:           primaryDiff = currentRect.top - candRect.bottom;
640:           secondaryDiff = Math.abs(candCenterX - currentCenterX);
641:         }
642: 
