await runTestCase('MalformedInputs', 'Non-Integer & Negative TMDB IDs', async () => {
  const malformedIds = ['abc', '-999', 'null'];
  for (const id of malformedIds) {
    const res = await request({ path: `/api/stream?tmdbId=${encodeURIComponent(id)}&type=movie` }, null, 25000);
    // Daemon should return 500/502 (or 400) because upstream fails or cannot find stream, but NOT crash
    assert([0, 400, 500, 502, 504].includes(res.statusCode), `Malformed ID "${id}" returned ${res.statusCode}`);
  }
  return `Server survived all malformed TMDB IDs and returned error responses`;
});

await runTestCase('MalformedInputs', 'Non-Existent TMDB ID (tmdbId=999999999)', async () => {
  const res = await request({ path: '/api/stream?tmdbId=999999999&type=movie' });
  assert([0, 404, 500, 502, 504].includes(res.statusCode), `Expected error status, got ${res.statusCode}`);
  if (res.statusCode !== 0) {
    assert(res.json && res.json.error, 'Expected error body');
  }
  return `Non-existent TMDB ID handled cleanly with error status ${res.statusCode}`;
});

await runTestCase('MalformedInputs', 'Oversized Input Fuzzing (10,000 char TMDB ID)', async () => {
  // Stresses WASM memory buffer allocation and bounds
  const hugeId = 'A'.repeat(10000);
  const res = await request({ path: `/api/stream?tmdbId=${hugeId}&type=movie` });
  // Should fail cleanly, must not crash the daemon process
  assert([0, 400, 414, 500, 502, 504].includes(res.statusCode), `Oversized ID returned unexpected ${res.statusCode}`);
  return `10,000 character ID handled without WASM trap or crash`;
});

await runTestCase('MalformedInputs', 'SQL Injection & XSS Payloads in Parameters', async () => {
  const injections = [
    "27205' OR '1'='1",
    '27205"; DROP TABLE streams; --',
    '<script>alert(1)</script>',
    '${jndi:ldap://127.0.0.1/a}',
  ];
  for (const payload of injections) {
    const res = await request({ path: `/api/stream?tmdbId=${encodeURIComponent(payload)}&type=movie` });
    assert([0, 400, 500, 502, 504].includes(res.statusCode), `Injection payload returned ${res.statusCode}`);
    if (res.statusCode !== 0 && res.headers && res.headers['content-type']) {
      assert(res.headers['content-type'].includes('application/json'), 'Response must remain application/json');
    }
  }
  return `All injection payloads returned controlled JSON error`;
});

await runTestCase('MalformedInputs', 'Path Traversal Attempt in Server Parameter', async () => {
  const traversals = [
    '../../etc/passwd',
    '..%2f..%2fetc%2fpasswd',
    '../../../crush.wasm',
  ];
  for (const s of traversals) {
    const res = await request({ path: `/api/stream?tmdbId=27205&type=movie&server=${encodeURIComponent(s)}` });
    // Server fallback should handle it or fail cleanly
    assert([0, 200, 400, 500, 502, 504].includes(res.statusCode), `Server traversal returned ${res.statusCode}`);
  }
  return `Server parameter traversal attempts neutralized`;
});

