}

// -----------------------------------------------------------------------------
// 2. Comprehensive TV Layout, Media & HLS Mocks for Real DOM Execution
// -----------------------------------------------------------------------------
function makeRect(left, top, width, height) {
  return {
    left: left,
    top: top,
    width: width,
    height: height,
    right: left + width,
    bottom: top + height,
    x: left,
    y: top
  };
}

function installLayoutMock(window) {
  window.Element.prototype.getBoundingClientRect = function () {
    // 1. If element or parent has display: none or hidden, return zero geometry
    if (this.style && (this.style.display === 'none' || this.style.visibility === 'hidden')) {
      return makeRect(0, 0, 0, 0);
    }
    const view = this.closest('.view');
    if (view && !view.classList.contains('active')) {
      return makeRect(0, 0, 0, 0);
    }

    // 2. Dynamic override via data-mock-rect
    const mockAttr = this.getAttribute('data-mock-rect');
    if (mockAttr) {
      try {
        const parsed = JSON.parse(mockAttr);
        return makeRect(parsed.left || 0, parsed.top || 0, parsed.width || 0, parsed.height || 0);
      } catch (_) {}
    }

    const id = this.id;

    // Header navigation pills
    if (this.classList.contains('nav-pill-item')) {
      const route = this.getAttribute('data-route');
      if (route === 'home') return makeRect(790, 28, 75, 40);
      if (route === 'movies') return makeRect(875, 28, 85, 40);
      if (route === 'series') return makeRect(970, 28, 80, 40);
      if (route === 'search') return makeRect(1060, 28, 80, 40);
    }

    // Hero buttons
    if (id === 'hero-play-btn') return makeRect(96, 460, 180, 56);
    if (id === 'hero-details-btn') return makeRect(292, 460, 140, 56);
    if (id === 'hero-list-btn') return makeRect(433, 460, 140, 56);

    // Details view buttons & cards
    if (id === 'details-play-btn') return makeRect(96, 450, 180, 56);
    if (id === 'details-trailer-btn') return makeRect(292, 450, 160, 56);
    if (this.classList.contains('season-pill')) {
      const s = parseInt(this.getAttribute('data-season') || '1', 10);
      return makeRect(96 + (s - 1) * 130, 580, 120, 44);
    }
    if (this.classList.contains('card-episode')) {
      const ep = parseInt(this.getAttribute('data-episode') || '1', 10);
      return makeRect(96 + (ep - 1) * 340, 660, 320, 180);
    }

    // Virtual keyboard keys
    if (this.classList.contains('key-btn')) {
      let col = 0, row = 0;
      if (this.parentElement) {
        col = Array.from(this.parentElement.children).indexOf(this);
        const rowEl = this.closest('.keyboard-row');
        if (rowEl && rowEl.parentElement) {
          row = Array.from(rowEl.parentElement.children).indexOf(rowEl);
        }
      }
      return makeRect(96 + col * 55, 200 + row * 55, 48, 48);
    }

    // Shelves and cards
    if (this.classList.contains('content-shelf')) {
      const shelfIdx = this.parentElement ? Array.from(this.parentElement.children).indexOf(this) : 0;
      return makeRect(0, 560 + shelfIdx * 400, 1920, 380);
    }
    if (this.classList.contains('card-poster')) {
      const rail = this.closest('.shelf-rail, #search-results-grid');
      let index = 0;
      if (rail) {
        index = Array.from(rail.children).indexOf(this);
      }
      const shelf = this.closest('.content-shelf');
      const isGrid = this.closest('#search-results-grid');
      if (isGrid) {
        const col = index % 6;
        const row = Math.floor(index / 6);
        return makeRect(96 + col * 280, 580 + row * 380, 220, 330);
      }
      const shelfIdx = (shelf && shelf.parentElement) ? Array.from(shelf.parentElement.children).indexOf(shelf) : 0;
      return makeRect(96 + index * 244, 680 + shelfIdx * 400, 220, 330);
    }

    // Player OSD Controls
    if (id === 'player-back-btn') return makeRect(96, 54, 56, 56);
    if (id === 'osd-rewind-btn') return makeRect(840, 940, 56, 56);
    if (id === 'osd-play-btn') return makeRect(912, 940, 96, 96);
    if (id === 'osd-forward-btn') return makeRect(1024, 940, 56, 56);
    if (id === 'osd-subtitles-btn') return makeRect(1420, 950, 180, 52);
    if (id === 'osd-server-btn') return makeRect(1616, 950, 180, 52);
    if (id === 'player-error-retry-btn') return makeRect(740, 580, 180, 52);
    if (id === 'player-error-switch-btn') return makeRect(940, 580, 180, 52);
    if (id === 'player-error-exit-btn') return makeRect(1140, 580, 160, 52);

    if (this.classList.contains('modal-list-item')) {
      const idx = this.parentElement ? Array.from(this.parentElement.children).indexOf(this) : 0;
      return makeRect(680, 320 + idx * 60, 560, 52);
    }

    return makeRect(96, 100, 100, 40);
  };

  window.Element.prototype.scrollIntoView = function (opts) {
    this._lastScrollIntoView = opts || true;
  };

  window.Element.prototype.scrollTo = function (x, y) {
    if (typeof x === 'object') {
      this.scrollLeft = x.left !== undefined ? x.left : (this.scrollLeft || 0);
      this.scrollTop = x.top !== undefined ? x.top : (this.scrollTop || 0);
    } else {
      this.scrollLeft = x !== undefined ? x : (this.scrollLeft || 0);
      this.scrollTop = y !== undefined ? y : (this.scrollTop || 0);
    }
  };
}

function installVideoMock(window) {
  const proto = window.HTMLMediaElement.prototype;

  function getState(el) {
    if (!el._mediaState) {
      el._mediaState = {
        currentTime: 0,
        duration: 7200,
        paused: true,
        ended: false,
        seeking: false,
        readyState: 0,
        bufferedRanges: [[0, 0]],
        playbackRate: 1.0,
        volume: 1.0,
        muted: false,
        textTracks: [],
        error: null,
        src: ''
      };
    }
    return el._mediaState;
  }

  Object.defineProperty(proto, 'currentTime', {
    get: function () { return getState(this).currentTime; },
    set: function (val) {
      const s = getState(this);
      const clamped = Math.max(0, Math.min(s.duration, Number(val) || 0));
      s.currentTime = clamped;
      s.seeking = true;
      this.dispatchEvent(new window.Event('seeking'));
      s.seeking = false;
      this.dispatchEvent(new window.Event('seeked'));
      this.dispatchEvent(new window.Event('timeupdate'));
    },
    configurable: true
  });

  Object.defineProperty(proto, 'duration', {
    get: function () { return getState(this).duration; },
    set: function (val) { getState(this).duration = Number(val) || 0; },
    configurable: true
  });

  Object.defineProperty(proto, 'paused', {
    get: function () { return getState(this).paused; },
    configurable: true
  });

  Object.defineProperty(proto, 'readyState', {
    get: function () { return getState(this).readyState; },
    configurable: true
  });

  proto.play = function () {
    const s = getState(this);
    s.paused = false;
    s.ended = false;
    s.readyState = 4;
    this.dispatchEvent(new window.Event('play'));
    this.dispatchEvent(new window.Event('playing'));
    return Promise.resolve();
  };

  proto.pause = function () {
    const s = getState(this);
    s.paused = true;
    this.dispatchEvent(new window.Event('pause'));
  };

  proto.load = function () {
    const s = getState(this);
    s.currentTime = 0;
    s.ended = false;
    this.dispatchEvent(new window.Event('loadstart'));
  };

  proto.canPlayType = function (type) {
    if (!type) return '';
    if (type.includes('mpegURL') || type.includes('mp4')) return 'probably';
    return 'maybe';
  };
}

function installHlsMock(window) {
  function MockHls(config) {
    this.config = config || {};
    this.media = null;
    this.url = null;
    this.destroyed = false;
    this._listeners = {};

    this.levels = [
      { bitrate: 2500000, width: 1280, height: 720, name: '720p' },
      { bitrate: 5000000, width: 1920, height: 1080, name: '1080p' }
    ];
    this.currentLevel = -1;
    this.subtitleTracks = [
      { id: 0, lang: 'en', name: 'English' }
    ];
    this.subtitleTrack = -1;
  }

  MockHls.prototype.on = function (event, cb) {
    if (!this._listeners[event]) this._listeners[event] = [];
    this._listeners[event].push(cb);
  };

  MockHls.prototype.trigger = function (event, data) {
    if (this._listeners[event]) {
      this._listeners[event].forEach(cb => {
        try { cb(event, data); } catch (_) {}
      });
    }
  };

  MockHls.prototype.loadSource = function (url) {
    this.url = url;
    const self = this;
    setTimeout(() => {
      self.trigger(MockHls.Events.MANIFEST_PARSED, { levels: self.levels });
    }, 10);
  };

  MockHls.prototype.attachMedia = function (media) {
    this.media = media;
    this.trigger(MockHls.Events.MEDIA_ATTACHED, { media });
  };

  MockHls.prototype.detachMedia = function () {
    this.media = null;
  };

  MockHls.prototype.stopLoad = function () {
    this.loading = false;
  };

  MockHls.prototype.destroy = function () {
    this.destroyed = true;
    this.media = null;
    this.url = null;
    this._listeners = {};
  };

  MockHls.isSupported = function () { return true; };

  MockHls.Events = {
    MANIFEST_PARSED: 'hlsManifestParsed',
    LEVEL_SWITCHED: 'hlsLevelSwitched',
    ERROR: 'hlsError',
    MEDIA_ATTACHED: 'hlsMediaAttached'
  };

  MockHls.ErrorTypes = {
    NETWORK_ERROR: 'networkError',
    MEDIA_ERROR: 'mediaError',
    OTHER_ERROR: 'otherError'
  };

  MockHls.ErrorDetails = {
    BUFFER_STALLED_ERROR: 'bufferStalledError',
    MANIFEST_LOAD_ERROR: 'manifestLoadError'
  };

  window.Hls = MockHls;
}

