// -----------------------------------------------------------------------------
async function runTier4() {
  console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`${C.bold}► RUNNING TIER 4: REAL-WORLD TV WORKLOAD SCENARIOS (7 Authentic Checks)${C.reset}`);
  console.log(`${C.cyan}========================================================================${C.reset}\n`);

  // =========================================================================
  // Scenario 1: Cold Boot to Hero Playback
  // =========================================================================
  await check('Scenario 1', 'Cold Boot to Hero Playback (F3, F4, F5, F8, F9)', async () => {
    const { window, document, app, nav, player, video } = createTier4Harness('home');

    // 1. Verify cold boot renders home viewport shell
    const homeView = document.getElementById('view-home');
    assert(homeView && homeView.classList.contains('active'), 'Home view must be active on cold boot');
    const heroBanner = document.querySelector('.hero-banner');
    assert(heroBanner, 'Hero banner must exist on TV home canvas');

    // 2. Initial focus on Hero CTA
    const heroBtn = document.getElementById('hero-play-btn');
    assert(heroBtn, 'Hero CTA play button must exist in DOM');
    nav.setFocus(heroBtn);
    assert.strictEqual(nav.getCurrentFocus(), heroBtn, 'Hero play button must receive spatial focus');
    assert(heroBtn.classList.contains('focused'), 'Hero play button must have .focused class');

    // 3. Dispatch Enter key to initiate stream playback
    heroBtn.click();

    // 4. Verify transition to Player view
    assert.strictEqual(app.state.currentView, 'player', 'App must transition to player view');
    const playerView = document.getElementById('view-player');
    assert(playerView && playerView.classList.contains('active'), 'Player view DOM must be active');

    // 5. Ingest video stream via proxy
    await player.loadStream({
      tmdbId: 27205,
      type: 'movie',
      title: 'Inception'
    });
    await player.play();

    assert.strictEqual(player.state, 'PLAYING', 'Player state must transition to PLAYING');
    assert(video.src.includes('127.0.0.1:8088/hls/proxy'), 'Video src must point to local streaming proxy');

    // 6. Verify OSD controls & auto-hide HUD timer
    const osdPlayBtn = document.getElementById('osd-play-btn');
    assert(osdPlayBtn, 'OSD Play/Pause control must exist in DOM');
    assert(window.PlayerOSDController._idleTimer !== null, 'OSD auto-hide timer must be active during playback');
  });

  // =========================================================================
  // Scenario 2: Catalog Browsing & Shelf Navigation across all 6 shelves
  // =========================================================================
  await check('Scenario 2', 'Catalog Browsing & Shelf Navigation across all 6 shelves (F3, F4, F5)', () => {
    const { document, nav, app } = createTier4Harness('home');

    // 1. Verify all 6 home shelves are present in DOM
    const shelves = document.querySelectorAll('#view-home .content-shelf');
    assert.strictEqual(shelves.length, 6, 'Must contain all 6 distinct home shelves');

    // 2. Populate and mock navigable cards across each shelf
    const firstCards = [];
    shelves.forEach((shelf, idx) => {
      let rail = shelf.querySelector('.shelf-rail');
      if (!rail) {
        rail = document.createElement('div');
        rail.className = 'shelf-rail';
        shelf.appendChild(rail);
      }
      let card = rail.querySelector('.card-poster');
      if (!card) {
        card = document.createElement('div');
        card.className = 'card-poster';
        card.setAttribute('data-nav', 'true');
        card.setAttribute('data-id', String(1000 + idx));
        rail.appendChild(card);
      }
      firstCards.push(card);
    });

    // 3. Focus first card on Shelf 0
    nav.setFocus(firstCards[0]);
    assert.strictEqual(nav.getCurrentFocus(), firstCards[0]);
    assert(firstCards[0].classList.contains('focused'), 'Shelf 0 card must have .focused class');

    // 4. Navigate down through each shelf sequentially
    for (let s = 1; s < shelves.length; s++) {
      nav.setFocus(firstCards[s]);
      assert.strictEqual(nav.getCurrentFocus(), firstCards[s], `Focus must shift to Shelf ${s}`);
      assert(firstCards[s].classList.contains('focused'), `Shelf ${s} card must have .focused class`);
      assert(!firstCards[s - 1].classList.contains('focused'), `Shelf ${s - 1} card must lose .focused class`);
    }

    // 5. Verify horizontal shelf auto-scroll calculation keeps card within safe margin
    const testRail = shelves[1].querySelector('.shelf-rail');
    nav.autoScrollShelf(firstCards[1]);
    assert(testRail.scrollLeft !== undefined, 'Shelf rail must maintain valid scrollLeft property');
    assert.strictEqual(app.state.currentView, 'home', 'Active view must remain home during shelf traversal');
  });

  // =========================================================================
  // Scenario 3: TV Series Binge Experience: Season tab to Episode Play
  // =========================================================================
  await check('Scenario 3', 'TV Series Binge Experience: Season tab to Episode Play (F4, F5, F6, F8, F9)', async () => {
    const { window, document, app, nav, player, details } = createTier4Harness('home');

    // 1. Navigate from Home to Series view
    app.switchView('series');
    assert.strictEqual(app.state.currentView, 'series', 'Active view must be series');

    // 2. Open TV Show in Details view
    app.openDetails({
      id: 1396,
      tmdbId: 1396,
      title: 'Breaking Bad',
      type: 'tv',
      number_of_seasons: 5
    });

    assert.strictEqual(app.state.currentView, 'details', 'Active view must be details');
    const detailsView = document.getElementById('view-details');
    assert(detailsView && detailsView.classList.contains('active'), 'Details view must be active in DOM');

    // 3. Verify Season selector tabs rendered
    details.renderSeasonSelector(5);
    const seasonTabs = detailsView.querySelectorAll('.season-pill');
    assert.strictEqual(seasonTabs.length, 5, 'Must render 5 season selector tabs');

    // 4. Click Season 2 tab
    seasonTabs[1].click();
    assert.strictEqual(details.activeSeason, 2, 'Active season must switch to Season 2');
    assert(seasonTabs[1].classList.contains('active'), 'Season 2 tab must have .active class');

    // 5. Render Season 2 episodes in episode rail
    const episodes = [
      { episode_number: 1, name: 'Seven Thirty-Seven' },
      { episode_number: 2, name: 'Grilled' },
      { episode_number: 3, name: 'Bit by a Dead Bee' }
    ];
    details.renderEpisodes(episodes, 2);

    const epCards = detailsView.querySelectorAll('.card-episode');
    assert.strictEqual(epCards.length, 3, 'Must render 3 episode cards');

    // 6. Select Episode 3 and launch player
    nav.setFocus(epCards[2]);
    assert.strictEqual(nav.getCurrentFocus(), epCards[2], 'Episode 3 must receive spatial focus');

    epCards[2].click();
    assert.strictEqual(app.state.currentView, 'player', 'Player must launch on episode click');

    // 7. Verify Player state & Back key return to Details
    assert.strictEqual(player.currentItem.episode, 3, 'Player payload must specify Episode 3');

    // Press webOS Back key (461)
    sendKey(window, 'Escape', 461);
    assert.strictEqual(app.state.currentView, 'details', 'Back key must restore Details view');
    assert.strictEqual(player.state, 'IDLE', 'Player must cleanly tear down on exit');
  });

  // =========================================================================
  // Scenario 4: Live Search & Back Focus Retention
  // =========================================================================
  await check('Scenario 4', 'Live Search & Back Focus Retention (F4, F5, F7, F6)', async () => {
    const { window, document, app, nav, search } = createTier4Harness('home');

    // 1. Navigate to Search view
    app.switchView('search');
    assert.strictEqual(app.state.currentView, 'search', 'Active view must be search');

    // 2. Verify virtual keyboard exists
    const keyboard = document.querySelector('.tv-keyboard-container');
    assert(keyboard, 'Virtual TV keyboard must exist in DOM');

    // 3. Focus a virtual key (e.g. key 'I')
    const keyI = keyboard.querySelector('[data-key="I"]') || keyboard.querySelector('.key-btn');
    assert(keyI, 'Key I button must exist on keyboard');
    nav.setFocus(keyI);
    assert.strictEqual(nav.getCurrentFocus(), keyI, 'Key I must receive spatial focus');

    // 4. Type query "INC" via virtual keyboard clicks
    keyI.click();
    const keyN = keyboard.querySelector('[data-key="N"]');
    if (keyN) keyN.click();
    const keyC = keyboard.querySelector('[data-key="C"]');
    if (keyC) keyC.click();

    const inputDisplay = document.getElementById('search-query-text');
    assert(inputDisplay && inputDisplay.textContent.length >= 1, 'Search query text must accumulate typed keys');

    // 5. Populate and move focus to search results grid
    const grid = document.getElementById('search-results-grid');
    assert(grid, 'Search results grid must exist in DOM');

    const resultCard = document.createElement('div');
    resultCard.className = 'card-poster';
    resultCard.setAttribute('data-nav', 'true');
    resultCard.setAttribute('data-id', '27205');
    resultCard.setAttribute('data-title', 'Inception');
    grid.appendChild(resultCard);

    // Release keyboard trap to allow focus shift to search results
    search.releaseTrap();
    nav.setFocus(resultCard);
    assert.strictEqual(nav.getCurrentFocus(), resultCard, 'Result card must receive focus');

    // 6. Click result card to open Details
    resultCard.click();
    assert.strictEqual(app.state.currentView, 'details', 'Details view must open on result card click');

    // 7. Press Back key (461) to unwind back to Search view
    sendKey(window, 'Escape', 461);
    assert.strictEqual(app.state.currentView, 'search', 'Back key must restore Search view');
  });

  // =========================================================================
  // Scenario 5: Stream Failure & Graceful Recovery with Server Switch
  // =========================================================================
  await check('Scenario 5', 'Stream Failure & Graceful Recovery with Server Switch (F2, F8, F9, F10)', async () => {
    const { document, player } = createTier4Harness('player');

    // 1. Ingest active stream on default server 'secret'
    await player.loadStream({
      tmdbId: 27205,
      type: 'movie',
      title: 'Inception'
    });
    await player.play();
    assert.strictEqual(player.state, 'PLAYING');
    assert.strictEqual(player.activeServer, 'secret');

    // 2. Set playhead position
    player.seek(120);
    assert.strictEqual(player.currentTime, 120, 'Playhead must be at 120s mark');

    // 3. Simulate stream stall / watchdog timeout
    player._onWatchdogTimeout();
    assert.strictEqual(player.state, 'ERROR', 'Player state must transition to ERROR on watchdog stall');

    const errorDialog = document.getElementById('player-error-modal');
    assert(errorDialog && errorDialog.style.display !== 'none', 'Error dialog must display on stall');

    // 4. Click "Switch Server" button on error dialog
    const switchBtn = document.getElementById('player-error-switch-btn');
    assert(switchBtn, 'Error dialog must contain Switch Server button');

    // Execute server fallback to 'Nebula'
    await player.switchServer('Nebula');
    await player.play();

    assert.strictEqual(player.activeServer, 'Nebula', 'Active server must switch to Nebula');
    assert.strictEqual(player.state, 'PLAYING', 'Player must recover and resume PLAYING state');
    assert.strictEqual(errorDialog.style.display, 'none', 'Error dialog must close after recovery');
  });

  // =========================================================================
  // Scenario 6: Extended Viewing & Resume Playback from localStorage
  // =========================================================================
  await check('Scenario 6', 'Extended Viewing & Resume Playback from localStorage (F8, F9, F10)', async () => {
    const { window, app, player } = createTier4Harness('player');

    const movieId = 27205;

    // 1. Play movie and progress to 45.2s
    await player.loadStream({
      tmdbId: movieId,
      type: 'movie',
      title: 'Inception'
    });
    await player.play();

    player.seek(45.2);
    player.savePlaybackPosition();

    // 2. Verify saved to real window.localStorage
    const stored = window.localStorage.getItem(`cinejoy_resume_${movieId}`);
    assert(stored, 'Resume position must be saved in localStorage');
    const parsed = JSON.parse(stored);
    assert.strictEqual(parsed.position, 45.2, 'Saved position must be exactly 45.2s');

    // 3. Exit player
    app.switchView('home');
    assert.strictEqual(player.state, 'IDLE', 'Player must be IDLE after exiting');

    // 4. Re-launch movie in player
    app.switchView('player');
    await player.loadStream({
      tmdbId: movieId,
      type: 'movie',
      title: 'Inception'
    });

    // 5. Verify restored playhead
    const restoredRecord = player._getSavedResumeRecord({ id: movieId, type: 'movie' });
    assert(restoredRecord, 'Player must find saved resume record');
    assert.strictEqual(restoredRecord.position, 45.2, 'Player must restore playhead from localStorage');
  });

  // =========================================================================
  // Scenario 7: Full Hierarchical Navigation Session & Backstack Unwind
  // =========================================================================
  await check('Scenario 7', 'Full Hierarchical Navigation Session & Backstack Unwind (F3, F4, F5, F6, F7, F8, F9)', () => {
    const { window, app, document } = createTier4Harness('home');

    // 1. Start on Home
    assert.strictEqual(app.state.currentView, 'home', 'Must start on Home view');

    // 2. Navigate to Movies view
    app.switchView('movies');
    assert.strictEqual(app.state.currentView, 'movies', 'Must transition to Movies view');
    assert(document.getElementById('view-movies').classList.contains('active'), 'Movies DOM must be active');

    // 3. Open Details view from Movies
    app.openDetails({
      id: 27205,
      tmdbId: 27205,
      title: 'Inception',
      type: 'movie'
    });
    assert.strictEqual(app.state.currentView, 'details', 'Must transition to Details view');
    assert.strictEqual(app.state.detailsOriginView, 'movies', 'Origin view must be recorded as movies');

    // 4. Open Player view from Details
    app.switchView('player', { tmdbId: 27205, type: 'movie' });
    assert.strictEqual(app.state.currentView, 'player', 'Must transition to Player view');

    // 5. Unwind Step 1: Back from Player -> Details
    sendKey(window, 'Escape', 461);
    assert.strictEqual(app.state.currentView, 'details', 'Back key must return to Details view');

    // 6. Unwind Step 2: Back from Details -> Movies (exact origin)
    sendKey(window, 'Escape', 461);
    assert.strictEqual(app.state.currentView, 'movies', 'Back key must return to Movies origin view');

    // 7. Unwind Step 3: Back from Movies -> Home
    sendKey(window, 'Escape', 461);
    assert.strictEqual(app.state.currentView, 'home', 'Back key must return to Home view');

    // 8. Unwind Step 4: Back on Home reaches webOS exit threshold
    const handledExit = app.handleBackNavigation();
    assert.strictEqual(handledExit, true, 'Back key on Home view must reach webOS exit threshold');
    assert.strictEqual(app.state.currentView, 'home', 'Home view must remain root view');
  });

  // =========================================================================
  // Summary & Exit Code
  // =========================================================================
  console.log(`\n${C.bold}${C.cyan}------------------------------------------------------------------------${C.reset}`);
  console.log(`  Tier 4 Workload Checks Completed: ${totalChecks}`);
  console.log(`  Passed Checks:                    ${C.green}${C.bold}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:                    ${failedChecks > 0 ? `${C.red}${C.bold}${failedChecks}` : '0'}${C.reset}`);
  console.log(`${C.cyan}------------------------------------------------------------------------${C.reset}\n`);

  if (failedChecks > 0 || totalChecks < 7) {
    console.error(`${C.red}${C.bold}VERDICT: TIER 4 FAILED (${failedChecks} failures, ${totalChecks}/7 checks)${C.reset}\n`);
    process.exit(1);
  } else {
    console.log(`${C.green}${C.bold}VERDICT: TIER 4 PASSED (7/7 checks 100% SUCCESS)${C.reset}\n`);
    process.exit(0);
  }
}

if (require.main === module) {
  runTier4();
}

module.exports = { runTier4 };

