    app.switchView('search');

    const searchInput = document.getElementById('search-input');
    assert(searchInput, 'Search input field must exist in DOM');

    // 1. Locate keyboard buttons for 'B', 'A', 'T'
    const keyB = document.querySelector('.tv-keyboard-container [data-key="B"]');
    const keyA = document.querySelector('.tv-keyboard-container [data-key="A"]');
    const keyT = document.querySelector('.tv-keyboard-container [data-key="T"]');
    assert(keyB && keyA && keyT, 'Letter keys B, A, T must exist in virtual keyboard');

    // Click keys sequentially
    keyB.click();
    keyA.click();
    keyT.click();
    assert.strictEqual(searchInput.value, 'BAT', 'Virtual keyboard input must assemble query BAT');

    // 2. Render mock search results
    search.renderResults([
      { id: 27205, title: 'Batman Begins', media_type: 'movie', poster_path: '/batman.jpg' }
    ]);

    const resultCards = Array.from(document.querySelectorAll('#search-results-grid .card-poster'));
    assert(resultCards.length > 0, 'Results grid must contain rendered search card');

    // 3. Shift focus to results grid
    search.releaseTrap();
    nav.setFocus(resultCards[0]);
    assert.strictEqual(nav.getCurrentFocus(), resultCards[0], 'Result card must receive spatial focus');

    // 4. Press Back key (461) to unwind focus back to virtual keyboard
    sendKey(window, 'Escape', 461);

    const activeFocus = nav.getCurrentFocus();
    assert(activeFocus, 'Focus must exist after back navigation');
    const inKeyboard = activeFocus.closest('.tv-keyboard-container') !== null;
    assert(inKeyboard, 'Back key must restore focus to virtual keyboard container');
  });

  // =========================================================================
  // T3.3 (F4 + F6): Season tab switching in Details rebuilds episode carousel
  // =========================================================================
  await check('T3.3', 'F4+F6: Season tab switching rebuilds episode carousel and auto-selects card 0', async () => {
