    assert.strictEqual(nav.getCurrentFocus(), subsBtn);

    // Open Subtitle Modal
    osd.openSubtitlesModal();

    const subsModal = document.getElementById('player-subtitles-modal');
    assert(subsModal && subsModal.style.display !== 'none', 'Subtitles modal must be visible');
    assert.strictEqual(nav.isTrapped(), true, 'SpatialNav must be trapped inside subtitles modal');

    // Select English track
    const trackItem = subsModal.querySelector('.modal-list-item');
    assert(trackItem, 'Subtitle track list item must exist');
    trackItem.click();

    // Verify modal closed, untrapped, and focus restored to subtitles button
    assert.strictEqual(subsModal.style.display, 'none', 'Subtitles modal must close after selection');
    assert.strictEqual(nav.isTrapped(), false, 'SpatialNav must untrap after closing modal');
    assert.strictEqual(nav.getCurrentFocus(), subsBtn, 'Focus must restore back to OSD subtitles button');
  });

  // =========================================================================
  // T3.5 (F4 + F9): Server Modal Focus Trapping & Alternate Server Selection
  // =========================================================================
  await check('T3.5', 'F4+F9: Server modal opens with SpatialNav.trap() -> Selects alternate mirror -> Restores HUD', async () => {
    const { window, document, player, osd, nav } = createTier3Harness('player');

    await player.loadStream({
      tmdbId: 27205,
      type: 'movie',
      title: 'Inception'
    });

    const serverBtn = document.getElementById('osd-server-btn');
    assert(serverBtn, 'OSD Server button must exist');
    nav.setFocus(serverBtn);

    // Open Server Modal
    osd.openServerModal();

    const serverModal = document.getElementById('player-server-modal');
    assert(serverModal && serverModal.style.display !== 'none', 'Server modal must be visible');
    assert.strictEqual(nav.isTrapped(), true, 'SpatialNav must be trapped inside server modal');

    // Select Nebula server
    const nebulaItem = serverModal.querySelector('[data-server="Nebula"]');
    assert(nebulaItem, 'Nebula server option must exist');
    nebulaItem.click();

    // Verify modal closed, server switched, untrapped, and focus restored
    assert.strictEqual(serverModal.style.display, 'none', 'Server modal must close after selection');
    assert.strictEqual(player.activeServer, 'Nebula', 'Active player server must switch to Nebula');
    assert.strictEqual(nav.isTrapped(), false, 'SpatialNav must untrap after modal exit');
    assert.strictEqual(nav.getCurrentFocus(), serverBtn, 'Focus must restore to OSD server button');
  });

