  // =========================================================================
  await check('T3.6', 'F2+F8: Stream resolver URL -> HLS proxy manifest rewriting -> Video stream ingestion', async () => {
    const rawManifest = '#EXTM3U\n#EXT-X-VERSION:7\n#EXT-X-STREAM-INF:BANDWIDTH=2500000\nvariant.m3u8\n';
    const baseUrl = 'https://lightspeed.st/hls/test/master.m3u8';
    const rewritten = hlsProxy.rewriteManifest(rawManifest, baseUrl, 'http://127.0.0.1:8088/hls/proxy?url=');

    assert(rewritten.includes('http://127.0.0.1:8088/hls/proxy?url='), 'Playlist lines must point to proxy');

    const { player, video } = createTier3Harness('player');
    await player.loadStream({
      tmdbId: 27205,
      type: 'movie',
      title: 'Inception'
    });

    const streamUrl = (player.hls && player.hls.url) || video.src;
    assert(streamUrl.includes('127.0.0.1:8088/hls/proxy'), 'Player must ingest stream through local streaming proxy');
  });

  // =========================================================================
  // T3.7 (F2 + F9): Subtitle Proxy + WebVTT + Video Text Track Rendering
  // =========================================================================
  await check('T3.7', 'F2+F9: Subtitle fetched via /proxy/sub -> WebVTT converted -> TextTrack attached', () => {
    const serverModule = fs.readFileSync(path.join(ROOT_DIR, 'server/index.js'), 'utf8');
    assert(serverModule.includes('convertSrtToVtt'), 'Server must implement convertSrtToVtt');

    const rawSrt = '1\n00:00:01,000 --> 00:00:04,000\nHello World\n';
    // Match server/index.js regex conversion
    const normalized = rawSrt.replace(/(\d{2}:\d{2}:\d{2}),(\d{3})/g, '$1.$2');
    const vtt = `WEBVTT\n\n${normalized.trim()}\n`;

    assert(vtt.startsWith('WEBVTT'), 'Converted subtitle must start with WEBVTT header');
    assert(vtt.includes('00:00:01.000 --> 00:00:04.000'), 'Timestamps must use dot notation');

    const { video, window } = createTier3Harness('player');
    const track = window.document.createElement('track');
    track.kind = 'subtitles';
    track.label = 'English';
    track.srclang = 'en';
    track.src = 'http://127.0.0.1:8088/proxy/sub?url=en.srt';
    video.appendChild(track);

    assert.strictEqual(video.children.length, 1);
    assert.strictEqual(video.children[0].label, 'English');
    assert(video.children[0].src.includes('/proxy/sub'), 'Track src must point to subtitle proxy');
  });

  // =========================================================================
