  // =========================================================================
  await check('T3.8', 'F8+F9+F10: Video stall event -> Buffering UI -> 15000ms watchdog -> Error modal', async () => {
    const { window, document, player, osd, video } = createTier3Harness('player');

    await player.loadStream({
      tmdbId: 27205,
      type: 'movie',
      title: 'Inception'
    });
    await player.play();
    assert.strictEqual(player.state, 'PLAYING');

