    video.dispatchEvent(new window.Event('waiting'));
    assert.strictEqual(osd.isBuffering, true, 'Buffering state must be true on video waiting event');

    // 2. Simulate 15s watchdog timeout
    player.handleFatalError('STREAM_TIMEOUT', 'Stream connection timed out after 15 seconds.');
    assert.strictEqual(player.state, 'ERROR', 'Player state must transition to ERROR');
    assert.strictEqual(osd.isBuffering, false, 'Buffering spinner must be hidden when error modal appears');

    const errorDialog = document.getElementById('player-error-dialog');
    assert(errorDialog && errorDialog.style.display !== 'none', 'Player error dialog must be visible on stall');
  });

  // =========================================================================
  // T3.9 (F9 + F10): Error Dialog "Switch Server" -> Alternate Resolver -> Resume Timestamp
  // =========================================================================
  await check('T3.9', 'F9+F10: Error modal "Switch Server" -> Queries alternate server -> Resumes playback time', async () => {
    const { window, document, player } = createTier3Harness('player');

    await player.loadStream({
      tmdbId: 27205,
      type: 'movie',
      title: 'Inception'
    });
    await player.play();
    player.seek(45.5);
    assert.strictEqual(player.currentTime, 45.5, 'Playhead must be at 45.5s');

    // Trigger error modal
    player.handleFatalError('STREAM_TIMEOUT', 'Stream connection timed out');
    const errorDialog = document.getElementById('player-error-dialog');
    assert(errorDialog && errorDialog.style.display !== 'none');

    // Click Switch Server button
    const switchBtn = document.getElementById('player-error-switch-btn');
    assert(switchBtn);
    switchBtn.click();

    // Switch server to Nebula
    await player.switchServer('Nebula');
    await player.play();

    assert.strictEqual(player.activeServer, 'Nebula', 'Active server must switch to Nebula');
    assert.strictEqual(player.state, 'PLAYING', 'Player must resume PLAYING state');
    assert.strictEqual(errorDialog.style.display, 'none', 'Error dialog must close');
    assert.strictEqual(player.currentTime, 45.5, 'Playhead position must be preserved at 45.5s');
  });

  // =========================================================================
  // T3.10 (F6 + F8 + F4): Details "Watch Now" -> Player -> Back Key 5-Stage Teardown -> Focus Restore
  // =========================================================================
  await check('T3.10', 'F6+F8+F4: Details "Watch Now" launches player -> Back key destroys player and restores focus', async () => {
    const { window, document, app, nav, player, details } = createTier3Harness('details');
    await details.loadDetails(27205, 'movie');

