    const updatedCards = Array.from(document.querySelectorAll('#view-movies .card-poster'));
    assert.strictEqual(movies.state.currentPage, 2, 'Movies catalog must advance to page 2');
    assert.strictEqual(updatedCards.length, 48, 'Cards count must double to 48 on page 2 load');
    assert.strictEqual(nav.getCurrentFocus(), cards[18], 'Focus position must remain retained at card 18');
  });

  // =========================================================================
  // T3.2 (F4 + F7): Virtual Keyboard Search -> Enter -> Grid Navigation -> Back Escape
  // =========================================================================
  await check('T3.2', 'F4+F7: Virtual Keyboard search input -> Enter -> D-pad to Grid -> Back escapes to keyboard', async () => {
    const { window, document, app, nav, search } = createTier3Harness('home');
    app.switchView('search');

    const queryDisplay = document.getElementById('search-query-text');
    assert(queryDisplay, 'Search query text display must exist in DOM');

    // 1. Locate keyboard buttons for 'B', 'A', 'T'
    const keyB = document.querySelector('.tv-keyboard-container [data-key="B"]');
    const keyA = document.querySelector('.tv-keyboard-container [data-key="A"]');
    const keyT = document.querySelector('.tv-keyboard-container [data-key="T"]');
    assert(keyB && keyA && keyT, 'Letter keys B, A, T must exist in virtual keyboard');

    // Click keys sequentially
    keyB.click();
    keyA.click();
    keyT.click();
    assert.strictEqual(search.query, 'BAT', 'Virtual keyboard input must assemble query BAT');
    assert.strictEqual(queryDisplay.textContent, 'BAT', 'Query display text must match BAT');

    // 2. Render mock search results
    search.renderResults([
      { id: 27205, title: 'Batman Begins', media_type: 'movie', poster_path: '/batman.jpg' }
    ]);

    const resultCards = Array.from(document.querySelectorAll('#search-results-grid .card-poster'));
    assert(resultCards.length > 0, 'Results grid must contain rendered search card');

    // 3. Shift focus to results grid
    search.releaseTrap();
    nav.setFocus(resultCards[0]);
    assert.strictEqual(nav.getCurrentFocus(), resultCards[0], 'Result card must receive spatial focus');

    // 4. Press Back key (461) to unwind focus back to virtual keyboard
    sendKey(window, 'Escape', 461);

    const activeFocus = nav.getCurrentFocus();
    assert(activeFocus, 'Focus must exist after back navigation');
    const inKeyboard = activeFocus.closest('.tv-keyboard-container') !== null;
    assert(inKeyboard, 'Back key must restore focus to virtual keyboard container');
  });

  // =========================================================================
  // T3.3 (F4 + F6): Season tab switching in Details rebuilds episode carousel
  // =========================================================================
  await check('T3.3', 'F4+F6: Season tab switching rebuilds episode carousel and auto-selects card 0', async () => {
    const { window, document, app, nav, details } = createTier3Harness('home');
    app.openDetails({
      id: 1396,
      tmdbId: 1396,
      type: 'tv',
      title: 'Breaking Bad',
      number_of_seasons: 5
    });

    await details.loadDetails(1396, 'tv');

    const seasonBar = document.querySelector('.season-selector-bar');
    assert(seasonBar && seasonBar.style.display !== 'none', 'Season selector bar must be displayed');

    const seasonPills = seasonBar.querySelectorAll('.season-pill');
    assert(seasonPills.length >= 2, 'At least 2 season tabs must be rendered');

    // Click Season 2 tab
    seasonPills[1].click();
    await details.loadSeason(1396, 2);

    assert.strictEqual(details.activeSeason, 2, 'Active season must be Season 2');

    const episodeCards = Array.from(document.querySelectorAll('#details-episodes-rail .card-episode'));
    assert(episodeCards.length >= 3, `Expected at least 3 episodes in Season 2, found ${episodeCards.length}`);

    nav.setFocus(episodeCards[0]);
    assert.strictEqual(nav.getCurrentFocus(), episodeCards[0], 'First episode card of Season 2 must receive focus');
    assert(episodeCards[0].textContent.includes('Seven Thirty-Seven'), 'First episode must be S02E01 Seven Thirty-Seven');
  });

  // =========================================================================
  // T3.4 (F4 + F9): Subtitle Modal Focus Trapping & Restoration
  // =========================================================================
  await check('T3.4', 'F4+F9: Subtitle modal opens with SpatialNav.trap() -> Untraps and restores HUD focus', async () => {
    const { window, document, player, osd, nav } = createTier3Harness('player');

    await player.loadStream({
      tmdbId: 27205,
      type: 'movie',
      title: 'Inception'
    });

    const subsBtn = document.getElementById('osd-subtitles-btn');
    assert(subsBtn, 'OSD Subtitles button must exist');
    nav.setFocus(subsBtn);
    assert.strictEqual(nav.getCurrentFocus(), subsBtn);

    // Open Subtitle Modal
    osd.openSubtitlesModal();

    const subsModal = document.getElementById('player-subtitles-modal');
    assert(subsModal && subsModal.style.display !== 'none', 'Subtitles modal must be visible');
    assert.strictEqual(nav.isTrapped(), true, 'SpatialNav must be trapped inside subtitles modal');

    // Select English track
    const trackItem = subsModal.querySelector('.modal-list-item');
    assert(trackItem, 'Subtitle track list item must exist');
    trackItem.click();

    // Verify modal closed, untrapped, and focus restored to subtitles button
    assert.strictEqual(subsModal.style.display, 'none', 'Subtitles modal must close after selection');
    assert.strictEqual(nav.isTrapped(), false, 'SpatialNav must untrap after closing modal');
    assert.strictEqual(nav.getCurrentFocus(), subsBtn, 'Focus must restore back to OSD subtitles button');
  });

  // =========================================================================
  // T3.5 (F4 + F9): Server Modal Focus Trapping & Alternate Server Selection
  // =========================================================================
  await check('T3.5', 'F4+F9: Server modal opens with SpatialNav.trap() -> Selects alternate mirror -> Restores HUD', async () => {
    const { window, document, player, osd, nav } = createTier3Harness('player');

    await player.loadStream({
      tmdbId: 27205,
      type: 'movie',
      title: 'Inception'
    });

    const serverBtn = document.getElementById('osd-server-btn');
    assert(serverBtn, 'OSD Server button must exist');
    nav.setFocus(serverBtn);

    // Open Server Modal
    osd.openServerModal();

    const serverModal = document.getElementById('player-server-modal');
    assert(serverModal && serverModal.style.display !== 'none', 'Server modal must be visible');
    assert.strictEqual(nav.isTrapped(), true, 'SpatialNav must be trapped inside server modal');

    // Select Nebula server
    const nebulaItem = serverModal.querySelector('[data-server="Nebula"]');
    assert(nebulaItem, 'Nebula server option must exist');
    nebulaItem.click();

    // Verify modal closed, server switched, untrapped, and focus restored
    assert.strictEqual(serverModal.style.display, 'none', 'Server modal must close after selection');
    assert.strictEqual(player.activeServer, 'Nebula', 'Active player server must switch to Nebula');
    assert.strictEqual(nav.isTrapped(), false, 'SpatialNav must untrap after modal exit');
    assert.strictEqual(nav.getCurrentFocus(), serverBtn, 'Focus must restore to OSD server button');
  });

  // =========================================================================
  // T3.6 (F2 + F8): Stream Resolver + HLS Proxy + Native Video Integration
  // =========================================================================
  await check('T3.6', 'F2+F8: Stream resolver URL -> HLS proxy manifest rewriting -> Video stream ingestion', async () => {
    const rawManifest = '#EXTM3U\n#EXT-X-VERSION:7\n#EXT-X-STREAM-INF:BANDWIDTH=2500000\nvariant.m3u8\n';
    const baseUrl = 'https://lightspeed.st/hls/test/master.m3u8';
    const rewritten = hlsProxy.rewriteManifest(rawManifest, baseUrl, 'http://127.0.0.1:8088/hls/proxy?url=');

    assert(rewritten.includes('http://127.0.0.1:8088/hls/proxy?url='), 'Playlist lines must point to proxy');

    const { player, video } = createTier3Harness('player');
    await player.loadStream({
      tmdbId: 27205,
      type: 'movie',
      title: 'Inception'
    });

    const streamUrl = (player.hls && player.hls.url) || video.src;
    assert(streamUrl.includes('127.0.0.1:8088/hls/proxy'), 'Player must ingest stream through local streaming proxy');
  });

  // =========================================================================
  // T3.7 (F2 + F9): Subtitle Proxy + WebVTT + Video Text Track Rendering
  // =========================================================================
  await check('T3.7', 'F2+F9: Subtitle fetched via /proxy/sub -> WebVTT converted -> TextTrack attached', () => {
    const serverModule = fs.readFileSync(path.join(ROOT_DIR, 'server/index.js'), 'utf8');
    assert(serverModule.includes('convertSrtToVtt'), 'Server must implement convertSrtToVtt');

    const rawSrt = '1\n00:00:01,000 --> 00:00:04,000\nHello World\n';
    const normalized = rawSrt.replace(/(\d{2}:\d{2}:\d{2}),(\d{3})/g, '$1.$2');
    const vtt = `WEBVTT\n\n${normalized.trim()}\n`;

    assert(vtt.startsWith('WEBVTT'), 'Converted subtitle must start with WEBVTT header');
    assert(vtt.includes('00:00:01.000 --> 00:00:04.000'), 'Timestamps must use dot notation');

    const { video, window } = createTier3Harness('player');
    const track = window.document.createElement('track');
    track.kind = 'subtitles';
    track.label = 'English';
    track.srclang = 'en';
    track.src = 'http://127.0.0.1:8088/proxy/sub?url=en.srt';
    video.appendChild(track);

    assert.strictEqual(video.children.length, 1);
    assert.strictEqual(video.children[0].label, 'English');
    assert(video.children[0].src.includes('/proxy/sub'), 'Track src must point to subtitle proxy');
  });

  // =========================================================================
  // T3.8 (F8 + F9 + F10): Network Stall -> Spinner -> Watchdog -> Error Dialog
  // =========================================================================
  await check('T3.8', 'F8+F9+F10: Video stall event -> Buffering UI -> 15000ms watchdog -> Error modal', async () => {
    const { window, document, player, video } = createTier3Harness('player');

    await player.loadStream({
      tmdbId: 27205,
      type: 'movie',
      title: 'Inception'
    });
    await player.play();
    assert.strictEqual(player.state, 'PLAYING');

    // 1. Simulate video buffering/waiting
    video.dispatchEvent(new window.Event('waiting'));
    assert.strictEqual(player.isBuffering, true, 'PlayerController buffering state must be true on waiting event');

    // 2. Simulate 15s watchdog timeout
    player.handleFatalError('STREAM_TIMEOUT', 'Stream connection timed out after 15 seconds.');
    assert.strictEqual(player.state, 'ERROR', 'Player state must transition to ERROR');
    assert.strictEqual(player.isBuffering, false, 'Player buffering state must reset to false on fatal error');

    const errorDialog = document.getElementById('player-error-dialog');
    assert(errorDialog && errorDialog.style.display !== 'none', 'Player error dialog must be visible on stall');
  });

  // =========================================================================
  // T3.9 (F9 + F10): Error Dialog "Switch Server" -> Alternate Resolver -> Resume Timestamp
  // =========================================================================
  await check('T3.9', 'F9+F10: Error modal "Switch Server" -> Queries alternate server -> Resumes playback time', async () => {
    const { window, document, player } = createTier3Harness('player');

    await player.loadStream({
      tmdbId: 27205,
      type: 'movie',
      title: 'Inception'
    });
    await player.play();
    player.seek(45.5);
    assert.strictEqual(player.currentTime, 45.5, 'Playhead must be at 45.5s');

    // Trigger error modal
    player.handleFatalError('STREAM_TIMEOUT', 'Stream connection timed out');
    const errorDialog = document.getElementById('player-error-dialog');
    assert(errorDialog && errorDialog.style.display !== 'none');

    // Click Switch Server button
    const switchBtn = document.getElementById('player-error-switch-btn');
    assert(switchBtn);
    switchBtn.click();

    // Switch server to Nebula
    await player.switchServer('Nebula');
    await player.play();

    assert.strictEqual(player.activeServer, 'Nebula', 'Active server must switch to Nebula');
    assert.strictEqual(player.state, 'PLAYING', 'Player must resume PLAYING state');
    assert.strictEqual(errorDialog.style.display, 'none', 'Error dialog must close');
    assert.strictEqual(player.currentTime, 45.5, 'Playhead position must be preserved at 45.5s');
  });

  // =========================================================================
  // T3.10 (F6 + F8 + F4): Details "Watch Now" -> Player -> Back Key 5-Stage Teardown -> Focus Restore
  // =========================================================================
  await check('T3.10', 'F6+F8+F4: Details "Watch Now" launches player -> Back key destroys player and restores focus', async () => {
    const { window, document, app, nav, player, details } = createTier3Harness('home');
    app.openDetails({
      id: 27205,
      tmdbId: 27205,
      type: 'movie',
      title: 'Inception'
    });
    assert.strictEqual(app.state.currentView, 'details');

    const playBtn = document.getElementById('details-play-btn');
    assert(playBtn, 'Details play button must exist');
    nav.setFocus(playBtn);
    assert.strictEqual(nav.getCurrentFocus(), playBtn);

    // Launch player from Details
    playBtn.click();
    assert.strictEqual(app.state.currentView, 'player', 'App must switch to player view');

    // Press Back key (461)
    sendKey(window, 'Escape', 461);

    assert.strictEqual(app.state.currentView, 'details', 'App must return to details view on Back key');
    assert.strictEqual(player.state, 'IDLE', 'Player must be destroyed back to IDLE state');
    assert.strictEqual(nav.getCurrentFocus(), playBtn, 'Focus must restore to details play button');
  });

  // =========================================================================
  // T3.11 (F5 + F6 + F4): Home Shelf Click -> Details Open -> Back Key Restores Shelf Card & scrollLeft
  // =========================================================================
  await check('T3.11', 'F5+F6+F4: Home card click opens details -> Back key restores exact card and shelf scrollLeft', () => {
    const { window, document, app, nav } = createTier3Harness('home');

    const shelfCards = Array.from(document.querySelectorAll('#view-home .card-poster'));
    assert(shelfCards.length >= 4, 'Home shelves must have multiple poster cards');
    const targetCard = shelfCards[3];
    const rail = targetCard.closest('.shelf-rail');
