    rail.scrollLeft = 440;
    nav.setFocus(targetCard);
    assert.strictEqual(nav.getCurrentFocus(), targetCard);

    // Click card to open Details
    targetCard.click();
    assert.strictEqual(app.state.currentView, 'details', 'Details view must open on card click');

    // Press Back key (461) to return to Home
    sendKey(window, 'Escape', 461);

    assert.strictEqual(app.state.currentView, 'home', 'Back key must restore Home view');
    assert.strictEqual(nav.getCurrentFocus(), targetCard, 'Focused card must be restored on Home view');
    assert(rail.scrollLeft >= 0, 'Shelf rail scrollLeft must be valid');
  });

